// === Tab: main ===
let particles = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(244);
	noStroke();

	let amount = round((width * height) / 11070.72);
	for (let i = 0; i < amount; i++)
		particles.push(new Particle(random(width), random(height)));
}

function draw() {
	background(244, 10);
	for (let i in particles) {
		particles[i].move(particles);
		particles[i].draw();
	}
}

// === Tab: boid ===
function Particle(x, y) {
	this.pos = createVector(x, y);
	this.vel = createVector(random(-5, 5), random(-5, 5));
	this.diameter = random(20, 25);
	this.distance = 100;

	let c = floor(random(3));
	if (c == 0)
		this.color = color(142, 198, 197);
	else if (c == 1)
		this.color = color(105, 131, 170);
	else if (c == 2)
		this.color = color(133, 102, 170);
}

Particle.prototype.move = function(particles) {
	let validParticles = [];
	for (let i in particles)
		if (particles[i].pos.dist(this.pos) < this.distance)
			validParticles.push(particles[i]);

	for (let i in validParticles) {
		this.vel.sub(validParticles[i].pos);
		this.vel.add(this.pos);
	}

	this.vel.limit(5);
	this.pos.add(this.vel);

	if (this.pos.x > width ) this.pos.x -= width;
	if (this.pos.x < 0     ) this.pos.x += width;
	if (this.pos.y > height) this.pos.y -= height;
	if (this.pos.y < 0     ) this.pos.y += height;
}

Particle.prototype.draw = function() {
	fill(this.color);
	ellipse(this.pos.x, this.pos.y, this.diameter, this.diameter);
}

